struct PrisonersGame {
    /// Whether to use the optimal strategy (following the cycle) or random guessing.
    let useOptimal: Bool
    /// The number of prisoners; must equal `drawers.count`.
    let prisonerCount: Int
    /// The drawers, each containing a slip with a prisoner number (1‑based).
    /// The array is shuffled and has exactly `prisonerCount` elements.
    let drawers: [Int]

    /// Simulates the prisoner's dilemma.
    /// - Returns: `true` if all prisoners find their number within 50 tries, otherwise `false`.
    func play() -> Bool {
        precondition(prisonerCount > 0, "Prisoner count must be positive")

        for prisonerNumber in 1...prisonerCount {
            var tries = 50
            var currentIndex = prisonerNumber - 1   // convert to 0‑based index

            while true {
                if useOptimal {
                    let slip = drawers[currentIndex]
                    if slip == prisonerNumber {
                        break   // success for this prisoner
                    }
                    // Follow the cycle: next drawer index is (slip - 1)
                    currentIndex = slip - 1
                } else {
                    // Random strategy: pick any drawer (with replacement)
                    let slip = drawers.randomElement()!
                    if slip == prisonerNumber {
                        break
                    }
                }

                tries -= 1
                if tries == 0 {
                    // This prisoner exhausted all attempts
                    return false
                }
            }
        }

        // All prisoners succeeded
        return true
    }
}

