struct PrisonersGame {
    /// Indicates whether the prisoners follow the optimal (cycle‑following) strategy.
    let useOptimal: Bool

    /// The shuffled boxes, each containing a slip with a number from 1 to `boxes.count`.
    let boxes: [Int]

    /// Simulates the 100 prisoners problem.
    ///
    /// The game is played as follows:
    /// - There are `boxes.count` prisoners, numbered from 1 to `boxes.count`.
    /// - Each prisoner may open at most 50 boxes (the classic limit for 100 prisoners).
    /// - If a prisoner finds his own number, he succeeds; otherwise he fails.
    /// - The whole group succeeds only if every prisoner succeeds.
    ///
    /// - Returns: `true` if all prisoners find their number, otherwise `false`.
    func play() -> Bool {
        // The original assembly traps if the array is empty.
        precondition(!boxes.isEmpty, "Boxes must not be empty")

        let maxAttempts = 50 // Fixed number of attempts (half of 100)

        // Iterate over each prisoner (1 … boxes.count)
        for prisonerNumber in 1...boxes.count {
            var found = false

            if useOptimal {
                // ---- Optimal (cycle‑following) strategy ----
                // Start by opening the box with the prisoner's own number (converted to 0‑based index)
                var index = prisonerNumber - 1
                for _ in 0..<maxAttempts {
                    let slip = boxes[index]      // open the box and read the slip
                    if slip == prisonerNumber {   // success: found his own number
                        found = true
                        break
                    }
                    index = slip - 1              // otherwise, next box to open is the one indicated by the slip
                }
            } else {
                // ---- Random strategy ----
                // Each attempt opens a completely random box (implementation uses `randomElement`)
                for _ in 0..<maxAttempts {
                    // Force‑unwrapping is safe because the array is non‑empty; the original assembly traps otherwise.
                    if boxes.randomElement()! == prisonerNumber {
                        found = true
                        break
                    }
                }
            }

            // If the current prisoner failed, the whole group fails.
            if !found {
                return false
            }
        }

        // All prisoners succeeded.
        return true
    }
}
