/// Returns `true` if the given integer is prime, `false` otherwise.
///
/// This implementation uses a classic optimized trial‑division algorithm:
/// - Excludes numbers less than 2, even numbers (except 2), and multiples of 3 (except 3).
/// - For numbers less than 25 that survive the above filters, the answer is known.
/// - All remaining candidates are checked only against divisors of the form 6k ± 1,
///   up to the square root of the number.
///
/// - Parameter n: The integer to test for primality.
/// - Returns: `true` if `n` is prime, otherwise `false`.
func isPrime(_ n: Int) -> Bool {
    guard n >= 2 else { return false }
    if n == 2 { return true }
    if n % 2 == 0 { return false }

    // n is odd and >= 3
    if n % 3 == 0 { return n == 3 }

    // All remaining numbers below 25 are prime: 5,7,11,13,17,19,23
    if n < 25 { return true }

    var i = 5
    while true {
        if n % i == 0 { return false }
        if n % (i + 2) == 0 { return false }
        i += 6
        // i * i > n  ⇔  i > n / i, and division avoids overflow.
        if i > n / i { break }
    }
    return true
}
