// alignCols takes a multi‑line string where fields are separated by '$' and aligns each column
// according to the given justification. It returns the realigned text as a single String.
func alignCols(input: String, align: Align) -> String {
    // Split the input into lines, then each line into fields (keeping empty fields).
    let lines = input.split(separator: "\n")
    var fieldsByLine = lines.map { $0.split(separator: "$", omittingEmptySubsequences: false) }

    // Determine the maximum number of columns and the width of each column.
    let columnCount = fieldsByLine.map { $0.count }.max() ?? 0
    var columnWidths = [Int](repeating: 0, count: columnCount)
    for line in fieldsByLine {
        for (i, field) in line.enumerated() {
            if field.count > columnWidths[i] {
                columnWidths[i] = field.count
            }
        }
    }

    // Helper to pad a field to the required width.
    func pad(_ s: Substring, width: Int, align: Align) -> String {
        let count = s.count
        if count >= width { return String(s) }
        let spaces = width - count
        switch align {
        case .left:
            return s + String(repeating: " ", count: spaces)
        case .right:
            return String(repeating: " ", count: spaces) + s
        case .center:
            let left = spaces / 2
            let right = spaces - left
            return String(repeating: " ", count: left) + s + String(repeating: " ", count: right)
        }
    }

    // Build each line with the properly padded fields.
    let alignedLines = fieldsByLine.map { line -> String in
        return line.enumerated().map { (i, field) in
            pad(field, width: columnWidths[i], align: align)
        }.joined(separator: " ")
    }

    return alignedLines.joined(separator: "\n")
}

