/// Aligns the columns of a multi‑line string according to the given alignment.
///
/// - Parameters:
///   - input: The input string containing rows separated by newlines.
///   - align: The desired alignment for each column: `.left`, `.center`, or `.right`.
/// - Returns: A new string where each column is padded to a uniform width,
///            columns are separated by a single space, and each line ends with a newline.
///            (A trailing space follows the last column of each line.)
func alignCols(input: String, align: Align) -> String {
    let widths = getColWidths(from: input)
    let lines = getLines(input: input)
    var result = ""

    for line in lines {
        let cols = line.split(separator: " ", omittingEmptySubsequences: false)
                       .map(String.init)

        for (col, width) in zip(cols, widths) {
            let pad = width - col.count
            let left, right: Int

            switch align {
            case .left:
                left = 0
                right = pad
            case .right:
                left = pad
                right = 0
            case .center:
                left = pad / 2
                right = pad - left
            }

            if left > 0 { result.append(String(repeating: " ", count: left)) }
            result.append(col)
            if right > 0 { result.append(String(repeating: " ", count: right)) }
            result.append(" ")   // column separator
        }

        result.append("\n")      // line terminator
    }

    return result
}
