extension BinaryInteger {
    /// Returns the number of positive divisors of this integer.
    ///
    /// The result is computed by prime factorisation. For zero, the return value is 0.
    func countDivisors() -> Int {
        // Work with the absolute value (magnitude) because the number of divisors
        // is defined only for positive integers.
        var n = self.magnitude
        guard n > 0 else { return 0 }

        // The final divisor count will be the product of (exponent + 1) for each prime factor.
        var result = 1

        // --- Factor out 2 -------------------------------------------------
        var exponent = 0
        while n & 1 == 0 {          // while n is even
            n >>= 1
            exponent += 1
        }
        if exponent > 0 {
            result *= exponent + 1
        }

        // --- Check odd divisors starting from 3 ---------------------------
        var divisor: Self.Magnitude = 3
        while divisor * divisor <= n {
            exponent = 0
            while n % divisor == 0 {
                n /= divisor
                exponent += 1
            }
            if exponent > 0 {
                result *= exponent + 1
            }
            divisor += 2           // only odd numbers
        }

        // --- If something remains, it is a prime factor -------------------
        if n > 1 {
            result *= 2
        }

        return result
    }
}
