import Foundation

// A reduced rational number type for exact fraction arithmetic.
struct Frac: Equatable {
    var numerator: Int
    var denominator: Int

    init(numerator: Int, denominator: Int) {
        precondition(denominator != 0)
        let g = gcd(numerator, denominator)
        self.numerator = numerator / g
        self.denominator = denominator / g
        // Ensure denominator is positive.
        if self.denominator < 0 {
            self.numerator = -self.numerator
            self.denominator = -self.denominator
        }
    }

    init(integerLiteral value: Int) {
        numerator = value
        denominator = 1
    }

    static func +(lhs: Frac, rhs: Frac) -> Frac {
        let newNum = lhs.numerator * rhs.denominator + rhs.numerator * lhs.denominator
        let newDen = lhs.denominator * rhs.denominator
        return Frac(numerator: newNum, denominator: newDen)
    }

    static func +=(lhs: inout Frac, rhs: Frac) {
        lhs = lhs + rhs
    }
}

// Greatest common divisor (Euclidean algorithm).
func gcd(_ a: Int, _ b: Int) -> Int {
    var a = abs(a), b = abs(b)
    while b != 0 {
        (a, b) = (b, a % b)
    }
    return a
}

// ------------------------------------------------------------
// Main program: search for perfect numbers up to 0x80000.
let limit = 0x80000 // 524288

for n in 2 ..< limit {
    // Start with 1/n (the reciprocal of n itself).
    var fraction = Frac(numerator: 1, denominator: n)

    // Only need to check possible divisors up to ceil(sqrt(n)).
    let root = Int(ceil(sqrt(Double(n))))
    for d in 2 ..< root {
        if n % d == 0 {
            // Found a divisor pair (d, n/d).
            fraction += Frac(numerator: 1, denominator: d)
            fraction += Frac(numerator: 1, denominator: n / d)
        }
    }

    // The sum of reciprocals of all divisors except 1 equals 1 iff n is perfect.
    if fraction == Frac(integerLiteral: 1) {
        print("\(n) is perfect")
    }
}
