/// Extends `BinaryInteger` to provide `lcm(with:)` using the GCD method.
extension BinaryInteger {
    /// Returns the least common multiple of `self` and `other`.
    ///
    /// This implementation first computes the greatest common divisor (GCD)
    /// and then calculates LCM as `(self / d) * other` to minimise overflow risk.
    /// - Parameter other: Another value of the same type.
    /// - Returns: The least common multiple.
    func lcm(with other: Self) -> Self {
        let d = gcd(with: other)
        return (self / d) * other
    }

    /// Returns the greatest common divisor of `self` and `other`.
    ///
    /// Uses the Euclidean algorithm.
    /// - Parameter other: Another value of the same type.
    /// - Returns: The greatest common divisor.
    private func gcd(with other: Self) -> Self {
        var a = self
        var b = other
        while b != 0 {
            let temp = b
            b = a % b
            a = temp
        }
        return a
    }
}

// Example usage:
// let a = 12
// let b = 15
// print(a.lcm(with: b)) // Output: 60
