final class AtomicBuckets {
    // Mutual exclusion semaphore (acts as a mutex)
    private let semaphore: DispatchSemaphore
    // Fixed-size bucket storage
    private var buckets: [Int]

    /// Creates a set of buckets with the given count, all initially set to `initialValue`.
    init(count: Int, initialValue: Int = 0) {
        self.semaphore = DispatchSemaphore(value: 1)
        self.buckets = Array(repeating: initialValue, count: count)
    }

    /// Atomically transfers up to `amount` from bucket `from` to bucket `to`.
    /// The actual transferred amount is limited by the available value in the source bucket.
    /// - Precondition: `from` and `to` are valid indices within the bucket array.
    func transfer(amount: Int, from fromIndex: Int, to toIndex: Int) {
        semaphore.wait()
        defer { semaphore.signal() }

        let available = buckets[fromIndex]
        let transfer = min(amount, available)   // do not exceed source balance

        // Standard operators trap on overflow, matching the assembly's jo checks
        buckets[fromIndex] -= transfer
        buckets[toIndex]   += transfer
    }
}
