/// Returns `true` if the given integer is prime.
func isPrime(_ n: Int) -> Bool {
    guard n >= 2 else { return false }
    if n == 2 || n == 3 { return true }
    if n % 2 == 0 { return false }
    var divisor = 3
    while divisor * divisor <= n {
        if n % divisor == 0 { return false }
        divisor += 2
    }
    return true
}

/// Returns the number of prime factors of `n` counted with multiplicity.
func primeFactorCount(_ n: Int) -> Int {
    var n = n
    var count = 0
    var divisor = 2
    while divisor * divisor <= n {
        if n % divisor == 0 {
            count += 1
            n /= divisor
            while n % divisor == 0 {
                n /= divisor
                count += 1
            }
        }
        divisor += divisor == 2 ? 1 : 2   // after 2, only odd numbers
    }
    if n > 1 {
        count += 1
    }
    return count
}

/// Returns `true` if `n` is an attractive number.
func isAttractive(_ n: Int) -> Bool {
    isPrime(primeFactorCount(n))
}

