extension BinaryInteger {
    /// Returns the prime factors of this integer in increasing order.
    ///
    /// The decomposition follows the mathematical definition: for `n > 1` the
    /// result is a sequence of primes whose product equals `n`; for `n <= 1`
    /// an empty array is returned. The algorithm works for any type conforming
    /// to `BinaryInteger`, including arbitrarily wide integer types.
    func primeDecomposition() -> [Self] {
        // Base case: numbers ≤ 1 have no prime factors.
        guard self > 1 else { return [] }

        // Extract all factors of 2.
        if self % 2 == 0 {
            return [2] + (self / 2).primeDecomposition()
        }

        // No more even factors – try odd divisors up to √self.
        let limit = Self(Double(self).squareRoot())   // safe because self ≤ Self.max
        var divisor: Self = 3
        while divisor <= limit {
            if self % divisor == 0 {
                return [divisor] + (self / divisor).primeDecomposition()
            }
            divisor += 2
        }

        // No divisor found – self is prime.
        return [self]
    }
}

