struct SimpleMovingAverage {
    /// The maximum number of values to keep in the window.
    var windowSize: Int
    /// The stored values within the current window.
    private var numbers: [Double] = []

    /// Creates a moving average calculator with the specified window size.
    /// - Parameter windowSize: The maximum number of values to retain.
    init(windowSize: Int) {
        self.windowSize = windowSize
    }

    /// Adds a new number to the window and returns the updated moving average.
    /// - Parameter value: The new value to add.
    /// - Returns: The average of the values in the window, or 0.0 if the window is empty.
    mutating func addNumber(_ value: Double) -> Double {
        // 1. Append the new value.
        numbers.append(value)

        // 2. If the window is now larger than allowed, remove the oldest value.
        if numbers.count > windowSize {
            numbers.removeFirst()
        }

        // 3. If the window is empty (e.g., windowSize == 0), return 0.
        guard !numbers.isEmpty else { return 0.0 }

        // 4. Compute the sum of all numbers in the window.
        let sum = numbers.reduce(0, +)

        // 5. Compute and return the average.
        return sum / Double(numbers.count)
    }
