struct BellTriangle<Element: BinaryInteger> {
    private var triangle: [[Element]]

    /// Creates the Bell triangle with the given number of rows (row 0 ... n).
    init(n: Int) {
        triangle = [[1]]
        for i in 1...n {
            // First element of the new row is the last element of the previous row.
            var row = [triangle[i-1][i-1]]
            for j in 1...i {
                // Recurrence: T(i, j) = T(i, j-1) + T(i-1, j-1)
                row.append(row[j-1] + triangle[i-1][j-1])
            }
            triangle.append(row)
        }
    }

    subscript(row: Int, col: Int) -> Element {
        // Precondition: 0 <= row < triangle.count and 0 <= col <= row
        return triangle[row][col]
    }
}

