/// - Parameter dna: The DNA string to mutate (inout).
/// - Returns: The action that was performed.
func mutate(dna: inout String) -> Action {
    // 1. Shuffle the indices to randomize order, then find the first index
    //    that points to a valid base (A, C, G, or T).
    guard let index = dna.indices.shuffled().first(where: { bases.contains(dna[$0]) }) else {
