    ///
    /// Uses exponentiation by squaring. Works with any `BinaryInteger`.
    static func modPow(_ base: Self, _ exp: Self, _ mod: Self) -> Self {
        guard mod != 0 else { fatalError("mod must be non-zero") }
        var result: Self = 1
        var base = base % mod
        var exp = exp
        while exp > 0 {
            if exp % 2 == 1 {
                result = (result * base) % mod
            }
            base = (base * base) % mod
            exp /= 2
        }
        return result
    }
}

