/// Returns the pair `(2p‑1, 3p‑2)` when `p` is prime and those two numbers are also prime,
/// and the resulting product `p·(2p‑1)·(3p‑2)` passes the Fermat test to base 2
/// (i.e. it is a Carmichael number).
///
/// This implements the classic Chernick construction of Carmichael numbers.
///
/// - Parameter p1: A candidate prime number.
/// - Returns: An array containing at most one tuple `(2p1‑1, 3p1‑2)`, or an empty array if
///            the conditions are not satisfied.
func carmichael<T: BinaryInteger>(p1: T) -> [(T, T)] {
    // Input must be prime.
    guard p1.isPrime else { return [] }

    let one = T(1)
    let two = T(2)
    let three = T(3)

    // Compute the two derived numbers.
    let q = two * p1 - one   // 2p‑1
    let r = three * p1 - two // 3p‑2

    // Both must be prime.
    guard q.isPrime, r.isPrime else { return [] }

    // The candidate Carmichael number.
    let n = p1 * q * r

    // Verify the Carmichael property using the Fermat test with base 2.
    // For numbers of this special form, the test is sufficient.
    if T.modPow(two, n - one, n) == one {
        return [(q, r)]
    }

    return []
}
