import Foundation

/// Returns the Chowla number for `n`: sum of the proper divisors of `n` excluding 1 and `n`.
func chowla(_ n: Int) -> Int {
    guard n > 1 else { return 0 }
    var sum = 0
    var i = 2
    while i * i <= n {
        if n % i == 0 {
            sum += i
            let j = n / i
            if i != j {
                sum += j
            }
        }
        i += 1
    }
    return sum
}

// -----------------------------------------------------------------
// 1. Print Chowla numbers for 1 ... 37
// -----------------------------------------------------------------
