    print("chowla(\(i)) = \(chowla(i))")
}

// -----------------------------------------------------------------
// 2. Count primes and find perfect numbers up to 10_000_000
//    using parallel segments.
// -----------------------------------------------------------------
let limit = 10_000_000
let lock = DispatchSemaphore(value: 1)          // protects shared structures
var perfect = [Int]()                           // perfect numbers found

// Limits we are interested in (upper bounds of the segments).
