// Prime counts for each limit will be stored here (non‑cumulative).
var primeCounts = Dictionary(uniqueKeysWithValues: limits.map { ($0, 0) })

// Build the segments: each covers numbers from (previous limit + 1) up to the current limit.
let segments: [(start: Int, end: Int)] = limits.enumerated().map { index, end in
    let start = index == 0 ? 1 : limits[index - 1] + 1
    return (start, end)
}

// Process all segments in parallel.
