/// Computes the Chowla number for a given integer `n`.
/// The Chowla number is the sum of the proper divisors of `n` excluding 1 and `n` itself.
/// - Parameter n: A value conforming to `SignedInteger`. Typically a positive integer.
/// - Returns: The sum of the proper divisors, or 0 if `n` ≤ 1.
func chowla<T: SignedInteger>(n: T) -> T {
    // Upper bound for the lower divisor: floor(sqrt(n)) + 1 (used as exclusive end).
    let limit = T(Double(n).squareRoot() + 1)

    // Generate the sequence 2, 3, ..., limit-1, filter out non‑divisors,
    // then sum each divisor and its complement (unless they are equal).
    return stride(from: T(2), to: limit, by: 1)
        .lazy
        .filter { n % $0 == 0 }
        .reduce(T(0)) { sum, divisor in
            let complement = n / divisor
            return sum + divisor + (complement == divisor ? 0 : complement)
        }
}
```

