import Foundation

/// Church numerals: functions that represent natural numbers via repeated composition.
struct Church<A> {
    /// The underlying function: given a transformation f, returns a function that applies f n times.
    let apply: (@escaping (A) -> A) -> (A) -> A
}

// ----- Basic constructors -----

/// The Church numeral for zero.
func zero<A>() -> Church<A> {
    return Church { _ in { x in x } }
}

/// The successor function: transforms a Church numeral n into n+1.
func succ<A>(_ n: Church<A>) -> Church<A> {
    return Church { f in
        { x in f(n.apply(f)(x)) }
    }
}

/// Builds a Church numeral from an integer.
func church(_ n: Int) -> Church<Int> {
    var result: Church<Int> = zero()
    for _ in 0..<n {
        result = succ(result)
    }
    return result
}

/// Converts a Church numeral back to an integer.
func unchurch(_ n: Church<Int>) -> Int {
    return n.apply { $0 + 1 } (0)
}

// ----- Arithmetic operations -----

/// Addition of Church numerals.
func add<A>(_ m: Church<A>, _ n: Church<A>) -> Church<A> {
    return Church { f in
        { x in m.apply(f)(n.apply(f)(x)) }
    }
}

/// Multiplication of Church numerals.
func mul<A>(_ m: Church<A>, _ n: Church<A>) -> Church<A> {
    return Church { f in m.apply(n.apply(f)) }
}

// ----- Lifting to higher kind (required for exponentiation) -----

/// Lifts a Church numeral to work on other Church numerals.
/// This turns a Church<A> into a Church<Church<A>> representing the same number.
func lift<A>(_ n: Church<A>) -> Church<Church<A>> {
    return Church<Church<A>> { f in
        Church<A> { x in
            n.apply(f.apply)(x)
        }
    }
}

// ----- Exponentiation -----

/// Exponentiation: base raised to the power of exponent.
/// Both arguments are ordinary Church<Int> numerals.
func exp(_ base: Church<Int>, _ exponent: Church<Int>) -> Church<Int> {
    let liftedExp = lift(exponent)                     // exponent as a Church<Church<Int>>
    let multiplyByBase = { (x: Church<Int>) in mul(base, x) }  // (Church<Int>) -> Church<Int>
    return liftedExp.apply(multiplyByBase)(church(1))  // apply multiplyByBase 'exponent' times to 1
}

// ----- Define the numbers 3 and 4 -----
