let four  = church(4)

// ----- Perform the computations -----
let a = unchurch(add(three, four))   // 3 + 4 = 7
let b = unchurch(mul(three, four))   // 3 * 4 = 12
let c = unchurch(exp(four, three))   // 4^3 = 64
let d = unchurch(exp(three, four))   // 3^4 = 81

// ----- Output the results -----
print([a, b, c, d])   // prints [7, 12, 64, 81]
