// Church numerals: represent natural numbers as higher‑order functions.
// For a type T, a Church numeral has type ((T) -> T) -> (T) -> T.
// The integer n is represented as the function that composes its argument f with itself n times.

/// The Church numeral for zero.
/// - Returns: A function that ignores its first argument (f) and returns the identity function on T.
func zero<T>(f: @escaping (T) -> T) -> (T) -> T {
    return { x in x }
}

/// Constructs the Church numeral corresponding to the given integer.
/// - Parameter n: The natural number to encode. (Negative values are treated as zero.)
/// - Returns: The Church numeral for n.
func church<T>(_ n: Int) -> ((T) -> T) -> (T) -> T {
    if n == 0 {
        // For zero we can return the statically defined `zero` function,
        // which requires no heap allocation.
        return zero
    } else {
        // For positive n, capture `n` in a closure context.
        return { f in
            return { x in
                var result = x
                // Apply f exactly n times.
                for _ in 0..<n {
                    result = f(result)
                }
                return result
            }
        }
    }
}
