import Foundation

/// A point in a 2‑D coordinate system.
struct Point: Equatable {
    let x: Double
    let y: Double

    /// Euclidean distance to another point.
    func distance(to other: Point) -> Double {
        let dx = x - other.x
        let dy = y - other.y
        return sqrt(dx * dx + dy * dy)
    }

    static func + (lhs: Point, rhs: Point) -> Point {
        Point(x: lhs.x + rhs.x, y: lhs.y + rhs.y)
    }

    static func - (lhs: Point, rhs: Point) -> Point {
        Point(x: lhs.x - rhs.x, y: lhs.y - rhs.y)
    }

    static func / (lhs: Point, scalar: Double) -> Point {
        Point(x: lhs.x / scalar, y: lhs.y / scalar)
    }

    static func * (lhs: Point, scalar: Double) -> Point {
        Point(x: lhs.x * scalar, y: lhs.y * scalar)
    }
}

/// A circle defined by its centre and radius.
struct Circle: Equatable {
    let centre: Point
    let radius: Double
}

/// The result of searching for circles of a given radius passing through two points.
enum CircleSolution {
    case none
    case one(Circle)
    case two(Circle, Circle)
}

extension Circle {
    /// Returns the circle(s) of the specified radius that pass through both points.
    ///
    /// - Parameters:
    ///   - p1: The first point.
    ///   - p2: The second point.
    ///   - radius: The desired radius.
    /// - Returns: `.none` if no such circles exist (radius ≤ 0, the points are identical,
    ///            or the distance between them exceeds 2×radius);
    ///            `.one(Circle)` if exactly one circle exists (the points are exactly 2×radius apart);
    ///            `.two(Circle, Circle)` if two distinct circles exist.
    static func circleBetween(_ p1: Point, _ p2: Point, withRadius radius: Double) -> CircleSolution {
        // Degenerate cases
        guard radius > 0 else { return .none }
        guard p1 != p2 else { return .none }

        let d = p1.distance(to: p2)
        let twiceRadius = 2 * radius
        guard d <= twiceRadius else { return .none }

        // Midpoint of the two points
        let midpoint = (p1 + p2) / 2.0

        // Half the distance between the points
        let halfD = d / 2.0

        // Distance from the midpoint to the centre(s). Use max to protect against
        // tiny negative values caused by floating‑point inaccuracies.
        let h = sqrt(max(0.0, radius * radius - halfD * halfD))

        // Vector from p1 to p2
        let delta = p2 - p1

        // A perpendicular direction (90° rotation)
        let perp = Point(x: -delta.y, y: delta.x)

        // Normalise the perpendicular vector (its length is d)
        let unitPerp = perp / d

        // Offset from the midpoint to each centre
        let offset = unitPerp * h

        let centre1 = midpoint + offset
        let centre2 = midpoint - offset

        // If the offset is zero the two centres coincide → only one circle
        if centre1 == centre2 {
            return .one(Circle(centre: centre1, radius: radius))
        } else {
            return .two(Circle(centre: centre1, radius: radius),
                        Circle(centre: centre2, radius: radius))
        }
    }
}
