import Swift

// -----------------------------------------------------------------
// Custom infinite/concatenated sequences used for continued fractions
// -----------------------------------------------------------------

/// An infinite sequence that cycles through a collection repeatedly.
struct CycledSequence<Base: Collection> {
    let base: Base

    init(base: Base) {
        self.base = base
        precondition(!base.isEmpty, "Cannot cycle an empty collection")
    }
}

extension CycledSequence: Sequence {
    struct Iterator: IteratorProtocol {
        let base: Base
        var index: Base.Index

        init(base: Base) {
            self.base = base
            self.index = base.startIndex
        }

        mutating func next() -> Base.Element? {
            guard !base.isEmpty else { return nil }
            let element = base[index]
            base.formIndex(after: &index)
            if index == base.endIndex {
                index = base.startIndex
            }
            return element
        }
    }

    func makeIterator() -> Iterator {
        Iterator(base: base)
    }
}

/// A finite sequence that first yields all elements of `first`,
/// then all elements of `second`.
struct ChainedSequence<First: Sequence, Second: Sequence>
    where First.Element == Second.Element
{
    let first: First
    let second: Second
}

extension ChainedSequence: Sequence {
    struct Iterator: IteratorProtocol {
        var firstIterator: First.Iterator
        var secondIterator: Second.Iterator

        init(firstIterator: First.Iterator, secondIterator: Second.Iterator) {
            self.firstIterator = firstIterator
            self.secondIterator = secondIterator
        }

        mutating func next() -> First.Element? {
            if let value = firstIterator.next() {
                return value
            } else {
                return secondIterator.next()
            }
        }
    }

    func makeIterator() -> Iterator {
        Iterator(firstIterator: first.makeIterator(),
                 secondIterator: second.makeIterator())
    }
}

// ---------------------------------------------------------
// Convenience extensions to call chained/cycled naturally
// ---------------------------------------------------------

extension Sequence where Self: Collection {
    func cycled() -> CycledSequence<Self> {
        CycledSequence(base: self)
    }
}

extension Sequence {
    func chained<Other: Sequence>(with other: Other) -> ChainedSequence<Self, Other>
        where Self.Element == Other.Element
    {
        ChainedSequence(first: self, second: other)
    }
