// Continued fraction evaluator (generalized form)
// ---------------------------------------------------------

/// Evaluates a generalized continued fraction of the form
///   a0 + b1/(a1 + b2/(a2 + ...))
/// using the first `iterations` terms of the sequences.
func continuedFraction<A: Sequence, B: Sequence>(
    _ a: A,
    _ b: B,
    iterations: Int
) -> Double where A.Element == Int, B.Element == Int {
    // Take the necessary number of terms.
    let aTerms = Array(a.prefix(iterations + 1))
    let bTerms = Array(b.prefix(iterations))
    guard !aTerms.isEmpty else { return .nan }

    var tail = 0.0
    // Process from the innermost term outward.
    for (aVal, bVal) in zip(aTerms.dropFirst().reversed(), bTerms.reversed()) {
        tail = Double(bVal) / (Double(aVal) + tail)
    }
    return Double(aTerms[0]) + tail
}

