///   - denominators: A sequence of integer denominator terms.
///   - numerators: A sequence of integer numerator terms.
///   - iterations: The number of term pairs to use. Must be non‑negative.
/// - Returns: The evaluated Double.
func continuedFraction<Denominators: Sequence, Numerators: Sequence>(
    _ denominators: Denominators,
    _ numerators: Numerators,
    iterations: Int
) -> Double where Denominators.Element == Int, Numerators.Element == Int {
