/// Computes a value using a continued‑fraction‑like recurrence:
/// ```
/// result = x₀ +   y₁
///                 ───────────────
///                 x₁ +   y₂
///                       ─────────
///                       x₂ + ... ─────────
///                                   yₙ
///                                  ──────
///                                   xₙ
/// ```
/// where for each `i`:
/// - `operation(i)` returns an array with at least two elements: `[xᵢ, yᵢ]` for i ≥ 1,  
/// - `operation(0)` returns an array with at least one element: `[x₀]`.
///
/// - Parameter n: The depth of the recurrence.
/// - Parameter operation: A closure that maps an integer index to an array of integers.
/// - Returns: The computed value as a Double.
func calculate(n: Int, operation: (Int) -> [Int]) -> Double {
    var accumulator: Double = 0.0

    // Evaluate from the deepest term up to the first (i = n down to 1).
    for i in (1...n).reversed() {
        let arr = operation(i)
        let numerator   = Double(arr[1])
        let denominator = Double(arr[0]) + accumulator
        accumulator = numerator / denominator
    }

    // Add the base term x₀ from operation(0).
    let baseArr = operation(0)
    return Double(baseArr[0]) + accumulator
}
