/// Computes the convex hull of a set of points using the gift wrapping (Jarvis march) algorithm.
func calculateConvexHull(fromPoints points: [Point]) -> [Point] {
    // If there are fewer than 3 points, the hull is the set itself.
    guard points.count >= 3 else { return points }

    // Find the starting point – usually the one with the smallest y,
    // and if tied, the smallest x.
    let startIndex = points.enumerated()
        .min { ($0.element.y, $0.element.x) < ($1.element.y, $1.element.x) }!
        .offset

    var hull: [Point] = []
    let n = points.count
    var current = startIndex

    repeat {
        // Add the current point to the hull.
        hull.append(points[current])

        // Start with the next point as a candidate (wrap around indices).
        var candidate = (current + 1) % n

        // Examine every point to find the one that is farthest to the left
        // relative to the current edge.
        for i in 0..<n {
            let orient = orientation(points[current], points[candidate], points[i])
            if orient == .counterClockwise {
                // This point is more counter‑clockwise, so it becomes the new candidate.
                candidate = i
            }
        }

        // Move to the next hull point.
        current = candidate
    } while current != startIndex   // Stop when we have completed the polygon.

    return hull
}

/// Determines the orientation of three points.
private func orientation(_ a: Point, _ b: Point, _ c: Point) -> Orientation {
    let cross = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)
    if cross > 0 {
        return .counterClockwise
    } else if cross < 0 {
        return .clockwise
    } else {
        return .collinear
    }
}

