/// Performs deconvolution (polynomial division) of two signals.
///
/// Given sequences `g` and `f`, computes `h` such that the convolution `f * h = g`.
/// This implementation assumes `f[0] != 0` and uses the standard recursive formula:
///
///   h[0] = g[0] / f[0]
///   h[i] = ( g[i] - Σ_{j=start}^{i-1} h[j] * f[i-j] ) / f[0],
///   where start = max(0, i - f.count + 1).
///
/// - Parameters:
///   - g: The output (convolved) signal.
///   - f: The filter (kernel) signal.
/// - Returns: The deconvolved signal `h` of length `g.count - f.count + 1`.
/// - Precondition: `f` must not be empty and `f[0] != 0`.
/// - Precondition: `g.count >= f.count - 1` (so the result length is non‑negative).
func deconv(g: [Double], f: [Double]) -> [Double] {
    let n = g.count - f.count + 1
    precondition(n >= 0, "g must be at least f.count - 1 elements long")
    precondition(!f.isEmpty && f[0] != 0, "f must have a non‑zero first element")

    var h = [Double](repeating: 0.0, count: n)
    let f0 = f[0]                     // constant divisor

    for i in 0..<n {
        // start the sum with g[i]
        h[i] = g[i]

        // subtract contributions from already computed h[j]
        let start = max(0, i - f.count + 1)
        for j in start..<i {
            h[i] -= h[j] * f[i - j]
        }

        // final division by f[0]
        h[i] /= f0
    }

    return h
}
