/// A doubly linked list.
struct DoublyLinkedList<Element> {
    private var head: Node<Element>?
    private var tail: Node<Element>?

    /// Specifies where to insert a new element.
    enum InsertLoc {
        case head
        case tail
        case after(Node<Element>)
        case before(Node<Element>)
    }

    /// Insert a new value into the list and return the created node.
    mutating func insert(_ value: Element, at location: InsertLoc) -> Node<Element> {
        let newNode = Node(value)

        switch location {
        case .head:
            newNode.next = head
            head?.prev = newNode
            head = newNode
            if tail == nil {
                tail = newNode
            }

        case .tail:
            newNode.prev = tail
            tail?.next = newNode
            tail = newNode
            if head == nil {
                head = newNode
            }

        case .after(let node):
            newNode.prev = node
            newNode.next = node.next
            node.next?.prev = newNode
            node.next = newNode
            if tail === node {
                tail = newNode
            }

        case .before(let node):
            newNode.prev = node.prev
            newNode.next = node
            node.prev?.next = newNode
            node.prev = newNode
            if head === node {
                head = newNode
            }
        }

        return newNode
    }

    /// Remove the given node from the list and return its value.
    @discardableResult
    mutating func remove(_ node: Node<Element>) -> Element? {
        let prev = node.prev
        let next = node.next

        if prev == nil {
            head = next
        } else {
            prev?.next = next
        }

        if next == nil {
            tail = prev
        } else {
            next?.prev = prev
        }

        node.prev = nil
        node.next = nil
        return node.value
    }
