/// Performs a three‑way partition (Dutch national flag) on the given array.
/// - Parameters:
///   - array: The array to partition (inout).
///   - mid: The pivot value. After partitioning, all elements `< mid` come first,
///          then all `== mid`, and finally all `> mid`.
func partition3<T: Comparable>(_ array: inout [T], mid: T) {
    var low = 0
    var midIndex = 0
    var high = array.count - 1

    while midIndex <= high {
        if array[midIndex] < mid {
            array.swapAt(low, midIndex)
            low += 1
            midIndex += 1
        } else if array[midIndex] == mid {
            midIndex += 1
        } else {
            array.swapAt(midIndex, high)
            high -= 1
        }
    }
}

