// Egyptian division (also known as the method of doubling)

/// Performs integer division using the ancient Egyptian algorithm,
/// returning both the quotient and the remainder.
///
/// - Parameters:
///   - dividend: The number to be divided (must be non‑negative).
///   - divisor:  The number to divide by (must be positive).
/// - Returns: A tuple `(quo: Int, rem: Int)` where `quo` is the quotient
///            and `rem` is the remainder.
/// - Precondition: `divisor > 0` and `dividend >= 0`.
func egyptianDivide(dividend: Int, divisor: Int) -> (quo: Int, rem: Int) {
    guard divisor != 0 else { fatalError("Division by zero") }
    guard dividend >= 0 && divisor > 0 else {
        // For simplicity this implementation handles only non‑negative
        // dividend and positive divisor.  A full implementation could be
        // extended to negative numbers as well.
        fatalError("Only non‑negative dividend and positive divisor are supported.")
    }

    // Build two parallel lists:
    //   powers: 2⁰, 2¹, 2², …
    //   doubles: divisor × power
    var powers: [Int] = [1]
    var doubles: [Int] = [divisor]

    while let last = doubles.last, last <= dividend {
        powers.append(powers.last! * 2)
        doubles.append(doubles.last! * 2)
    }

    var remainder = dividend
    var quotient = 0

    // Go through the lists in descending order; whenever the double fits
    // into the current remainder, subtract it and add the corresponding power.
    for i in stride(from: doubles.count - 1, through: 0, by: -1) {
        if doubles[i] <= remainder {
            remainder -= doubles[i]
            quotient += powers[i]
        }
    }

    return (quotient, remainder)
}

