extension BinaryInteger {
    /// Returns the quotient and remainder of Egyptian division.
    ///
    /// - Parameter divisor: The divisor.
    /// - Returns: A tuple `(quo: Self, rem: Self)` such that
    ///   `self = quo * divisor + rem` and `0 <= rem.magnitude < divisor.magnitude`.
    /// - Precondition: `divisor != 0`.
    func egyptianDivide(by divisor: Self) -> (quo: Self, rem: Self) {
        guard divisor != 0 else { fatalError("Division by zero") }

        let dividendAbs = magnitude
        let divisorAbs = divisor.magnitude

        // Generate an infinite sequence of (power of two, product) pairs.
        let pairs = (1...).lazy.map { n -> (power: Magnitude, product: Magnitude) in
            let power = Magnitude(1) << (n - 1)
            return (power, divisorAbs * power)
        }

        // Keep only pairs whose product does not exceed the dividend.
        let validPairs = pairs.prefix { $0.product <= dividendAbs }

        // Process from largest to smallest, accumulating quotient and remainder.
        let (quotientAbs, remainderAbs) = validPairs.reversed().reduce(
            (Magnitude(0), dividendAbs)
        ) { acc, pair in
            var (q, r) = acc
            if pair.product <= r {
                q += pair.power
                r -= pair.product
            }
            return (q, r)
        }

        // Apply the correct sign to the quotient.
        let quotientSign = self.signum() * divisor.signum()
        let quotient = Self(quotientAbs) * quotientSign

        // Compute the remainder using the division identity.
        let remainder = self - quotient * divisor

        return (quo: quotient, rem: remainder)
    }
}
