func isPrime(_ n: Int) -> Bool {
    if n < 2 { return false }
    if n % 2 == 0 { return n == 2 }
    if n % 3 == 0 { return n == 3 }
    var i = 5
    while i * i <= n {
        if n % i == 0 { return false }
        i += 2
        if n % i == 0 { return false }
        i += 4
    }
    return true
}

