/// Searches for a candidate factor of the Mersenne number 2^exp - 1.
/// The function tests values of k from 0 to 16383 and returns the first
/// number of the form 2·k·exp + 1 that satisfies:
///   - it is prime,
///   - it is congruent to 1 or 7 modulo 8,
///   - and exp.modPow(exp: candidate, mod: 2) == 1 (i.e., exp is odd).
/// If no such candidate is found, nil is returned.
/// The function traps (via integer overflow) if any intermediate
/// arithmetic operation overflows.
///
/// - Parameter exp: The exponent (typically a positive integer).
/// - Returns: A candidate factor or nil if none is found.
func mFactor(exp: Int) -> Int? {
    // Precondition: 2 * exp does not overflow – enforced by the multiplication.
    let twiceExp = exp * 2

    // Iterate over k = 0 ..< 16384  (0x4000)
    for k in 0 ..< 0x4000 {
        // Compute candidate = 2 * exp * k + 1.
        // Both multiplications will trap on overflow.
        let product = k * twiceExp
        let candidate = product | 1   // product is even, so this adds 1.

        // Check primality.
        guard candidate.isPrime else { continue }

        // Check modulo 8 condition (using Swift's remainder operator,
        // which for negative candidates gives a negative remainder that
        // will never equal 1 or 7, thus correctly skipping them).
        let rem = candidate % 8
        guard rem == 1 || rem == 7 else { continue }

        // Finally, verify that exp.modPow(exp: candidate, mod: 2) == 1.
        // This is equivalent to checking that exp is odd.
        if exp.modPow(exp: candidate, mod: 2) == 1 {
            return candidate
        }
    }

    return nil
