class Farey {
    let n: Int

    init(_ n: Int) {
        self.n = n
    }

    // The Farey sequence of order n as an array of (numerator, denominator)
    var sequence: [(Int, Int)] {
        var a = 0, b = 1
        var c = 1, d = n
        var seq = [(a, b)]

        while c <= n {
            let k = (n + b) / d
            (a, b, c, d) = (c, d, k * c - a, k * d - b)
            seq.append((a, b))
        }

        return seq
    }

    // A ready‑to‑print representation of the whole sequence
    var formattedSequence: String {
        let fractions = sequence.map { "\($0.0)/\($0.1)" }
        return "F(\(n)): " + fractions.joined(separator: " ")
