import Foundation

/// Adds two non‑negative decimal numbers represented as strings.
/// - Returns: The sum as a decimal string.
func addStrings(_ a: String, _ b: String) -> String {
    let aChars = Array(a)
    let bChars = Array(b)
    var i = aChars.count - 1
    var j = bChars.count - 1
    var carry = 0
    var result = [Character]()

    while i >= 0 || j >= 0 || carry > 0 {
        let digitA = i >= 0 ? aChars[i].wholeNumberValue! : 0
        let digitB = j >= 0 ? bChars[j].wholeNumberValue! : 0
        let sum = digitA + digitB + carry
        result.append(Character("\(sum % 10)"))
        carry = sum / 10
        i -= 1
        j -= 1
    }

    return String(result.reversed())
}

/// Computes the Shannon entropy (base 2) of the digit distribution in the array.
/// - Parameter digits: Array of decimal digits (0‑9).
/// - Returns: Entropy value; 0 for an empty array.
func getEntropy(_ digits: [Int]) -> Double {
    guard !digits.isEmpty else { return 0 }
    var frequency = [Int: Int]()
    for d in digits {
        frequency[d, default: 0] += 1
    }
    let total = Double(digits.count)
    var entropy = 0.0
    for count in frequency.values {
        let p = Double(count) / total
        entropy -= p * log2(p)
    }
    return entropy
}

