struct Point {
    let x: Double
    let y: Double
}

struct Line {
    let p1: Point
    let p2: Point

    var slope: Double {
        let dx = p2.x - p1.x
        // Vertical lines are represented by NaN.
        guard dx != 0 else { return .nan }
        return (p2.y - p1.y) / dx
    }

    /// Returns the intersection point of this line with another line,
    /// or `nil` if the lines are parallel (slopes equal).
    func intersection(of other: Line) -> Point? {
        let m1 = self.slope
        let m2 = other.slope

        // Parallel lines (including coincident) have no single intersection.
        guard m1 != m2 else { return nil }

        // Handle exactly one vertical line specially.
        switch (m1.isNaN, m2.isNaN) {
        case (true, false):
            // `self` is vertical.
            let x = p1.x
            let y = m2 * (x - other.p1.x) + other.p1.y
            return Point(x: x, y: y)

        case (false, true):
            // `other` is vertical.
            let x = other.p1.x
            let y = m1 * (x - p1.x) + p1.y
            return Point(x: x, y: y)

        default:
            // Both slopes are finite, or both NaN (which yields a NaN point).
            let x1 = p1.x
            let y1 = p1.y
            let x2 = other.p1.x
            let y2 = other.p1.y

            let x = (m1 * x1 - m2 * x2 + y2 - y1) / (m1 - m2)
            let y = m2 * (x - x2) + y2   // could also use m1
            return Point(x: x, y: y)
        }
    }
}
