import Foundation

/// Returns an array of dates representing the last Sunday of each month in the given year.
/// - Parameter year: The year for which to compute the last Sundays.
/// - Returns: An array of `Date` objects, one for the last Sunday of each month.
func lastSundays(of year: Int) -> [Date] {
    let calendar = Calendar.current

    return (1...12).map { month in
        // Start with the first day of the month following the current one.
        var components = DateComponents()
        components.year = year
        components.month = month + 1   // next month (handles December -> 13 seamlessly)
        components.day = 1

        let firstOfNextMonth = calendar.date(from: components)!
        let weekday = calendar.component(.weekday, from: firstOfNextMonth)

        // Adjust the day component to land on the last Sunday of the original month.
        //   weekday == 1 (Sunday)  → need to go back 7 days (day = 1 - 7 = -6)
        //   otherwise               → go back (weekday - 1) days (day = 2 - weekday)
        components.day = weekday == 1 ? -6 : 2 - weekday

        return calendar.date(from: components)!
    }
}
