/// Determines if a number is "gapful".
///
/// A gapful number is at least 100 and is divisible by the integer formed
/// by its first and last digit.
///
/// - Parameter n: The number to test.
/// - Returns: `true` if the number is gapful, otherwise `false`.
func isGapful(_ n: Int) -> Bool {
    guard n >= 100 else { return false }
    var firstDigit = n
    while firstDigit >= 10 {
        firstDigit /= 10
    }
    let divisor = firstDigit * 10 + n % 10
    return n % divisor == 0
}

