/// Generates a random Fischer random chess (Chess960) starting position.
///
/// The implementation is a direct translation of the provided assembly code.
/// It builds the position file by file (from left to right) while respecting
/// the classic Chess960 constraints:
/// - Exactly one king and one queen.
/// - Two rooks, with the king placed between them.
/// - Two bishops on opposite‑colored squares.
/// - Two knights with no additional restrictions.
///
/// The algorithm maintains counts of already placed pieces and a parity
/// memory for the first bishop. In each iteration it computes which pieces
/// are still allowed at the current file, then chooses one randomly.
func get960Position() -> String {
    // Unicode symbols for the white chess pieces.
    let king   = "\u{2654}"   // ♔
    let queen  = "\u{2655}"   // ♕
    let rook   = "\u{2656}"   // ♖
    let bishop = "\u{2657}"   // ♗
    let knight = "\u{2658}"   // ♘

    var result = ""               // the final position string
    var counts: [String: Int] = [:]   // number of times each piece has been placed
    var firstBishopParity: Int? = nil // parity (file % 2) of the first bishop, if any

    // Process the eight files in order (1 = leftmost, 8 = rightmost).
    for file in 1...8 {
        // An array of five optional strings – one slot per piece type.
        // The order is: [king, queen, rook, bishop, knight].
        var candidates: [String?] = .init(repeating: nil, count: 5)

        // ------------------------------------------------------------
        // King – may be placed only after exactly one rook and before the king itself.
        if counts[rook, default: 0] == 1 && counts[king, default: 0] == 0 {
            candidates[0] = king
        }

        // ------------------------------------------------------------
        // Queen – allowed on the first file unconditionally, otherwise only if not yet placed.
        if file == 1 {
            candidates[1] = queen
        } else if counts[queen, default: 0] == 0 {
            candidates[1] = queen
        }

        // ------------------------------------------------------------
        // Rook – first rook anytime; second rook only after the king is placed.
        let rookCount = counts[rook, default: 0]
        if rookCount == 0 || (rookCount == 1 && counts[king, default: 0] == 1) {
            candidates[2] = rook
        }

        // ------------------------------------------------------------
        // Bishop – parity constraint (bishops must be on opposite colors).
        let bishopCount = counts[bishop, default: 0]
        let conditionA = (bishopCount >= 2) || (firstBishopParity != nil)
        let parityMatch = firstBishopParity.map { $0 == (file % 2) } ?? false
        if !(conditionA && parityMatch) {
            candidates[3] = bishop
        }

        // ------------------------------------------------------------
        // Knight – only a simple count restriction (max two).
        if counts[knight, default: 0] <= 1 {
            candidates[4] = knight
        }

        // Obtain the list of actually allowed pieces and pick one at random.
        let available = candidates.compactMap { $0 }
        guard let chosen = available.randomElement() else {
            // The original assembly contains a fallback for the (theoretical) case
            // that no candidate exists: it inserts a bishop just before the last
            // character of the result and then exits.
            if let lastIndex = result.index(result.endIndex, offsetBy: -1,
