/// Returns the start index, end index (inclusive), and sum of the maximum subarray.
/// - Parameter sequence: The array of integers to analyze.
/// - Returns: A tuple (start, end, maxSum).
func maxSubseq(sequence: [Int]) -> (start: Int, end: Int, maxSum: Int) {
    // Kadane's algorithm
    var maxSum = sequence[0]
    var currentSum = sequence[0]
    var start = 0
    var tempStart = 0
    var end = 0

    for i in 1..<sequence.count {
        if currentSum + sequence[i] < sequence[i] {
            currentSum = sequence[i]
            tempStart = i
        } else {
            currentSum += sequence[i]
        }

        if currentSum > maxSum {
            maxSum = currentSum
            start = tempStart
            end = i
        }
    }
    return (start, end, maxSum)
}

