func maxSubseq(sequence: [Int]) -> (Int, Int, Int) {
    var maxSum = 0, thisSum = 0, i = 0
    var start = 0, end = -1
    for (j, seq) in sequence.enumerated() {
        thisSum += seq
        if thisSum < 0 {
            i = j + 1
            thisSum = 0
        } else if (thisSum > maxSum) {
            maxSum = thisSum
            start = i
            end = j
        }
    }
