/// Finds the contiguous subarray with the maximum sum.
///
/// This function implements a variant of Kadane's algorithm that allows an empty
/// subarray with sum 0. When multiple subarrays achieve the same maximum sum,
/// the first one (with the smallest start index) is chosen.
///
/// - Parameter sequence: An array of integers.
/// - Returns: A tuple `(start, end)` where `start` is the inclusive start index
///            and `end` is the exclusive end index of the maximum subarray.
///            If the maximum sum is 0 (i.e., the empty subarray is optimal),
///            returns `(0, 0)`.
func maxSubseq(sequence: [Int]) -> (Int, Int) {
    guard !sequence.isEmpty else { return (0, 0) }

    var maxSum = 0
    var curSum = 0
    var curStart = 0
    var best: (start: Int, end: Int)? = nil   // end is inclusive

    for (index, value) in sequence.enumerated() {
        curSum += value

        if curSum < 0 {
            // Discard the current subarray and start a new one after this index.
            curSum = 0
            curStart = index + 1
        } else if curSum > maxSum {
            // Found a better subarray.
            maxSum = curSum
            best = (curStart, index)
        }
        // When curSum == maxSum, keep the earlier subarray.
    }

    guard let (start, end) = best else {
        // No subarray with a positive sum; return the empty range.
        return (0, 0)
    }

    // Convert inclusive end to exclusive end.
    return (start, end + 1)
}
