// ---------------------------------------------------------------------
// hashJoin: Equi-join on the first element (key) of two sequences.
// Returns an array of tuples (valueFromT1, key, valueFromT2).
// ---------------------------------------------------------------------
func hashJoin<K: Hashable, V1, V2>(_ t1: [(K, V1)], _ t2: [(K, V2)]) -> [(V1, K, V2)] {
    var dict: [K: [V2]] = [:]                     // group t2 values by key
    for (key, val) in t2 {
        dict[key, default: []].append(val)
    }

    var result: [(V1, K, V2)] = []
    for (key, val) in t1 {
        if let matches = dict[key] {
            for v2 in matches {
                result.append((val, key, v2))
            }
        }
    }
    return result
}

