/// Calculates the great-circle distance between two points on Earth using the haversine formula.
///
/// - Parameters:
///   - lat1: Latitude of point 1 (in degrees)
///   - lon1: Longitude of point 1 (in degrees)
///   - lat2: Latitude of point 2 (in degrees)
///   - lon2: Longitude of point 2 (in degrees)
/// - Returns: Distance in kilometers (based on the Earth radius constant used in the original assembly).
func haversine(lat1: Double, lon1: Double, lat2: Double, lon2: Double) -> Double {
    let earthRadius: Double = 6371.0   // Earth radius in km (the original assembly constant was most likely this value)

    let degToRad = Double.pi / 180.0
    let lat1Rad = lat1 * degToRad
    let lat2Rad = lat2 * degToRad
    let lon1Rad = lon1 * degToRad
    let lon2Rad = lon2 * degToRad

    let deltaLat = lat2Rad - lat1Rad
    let deltaLon = lon2Rad - lon1Rad

    let sinHalfDeltaLat = sin(deltaLat / 2)
    let sinHalfDeltaLon = sin(deltaLon / 2)

    let a = sinHalfDeltaLat * sinHalfDeltaLat
            + cos(lat1Rad) * cos(lat2Rad) * sinHalfDeltaLon * sinHalfDeltaLon

    let c = 2 * asin(sqrt(a))   // central angle in radians
    return earthRadius * c
}
