/// Computes the Jacobi symbol `(a | n)` for integers `a` and an odd positive integer `n`.
///
/// The implementation follows the binary algorithm derived from the provided assembly code:
/// - reduces `a` modulo `n` into the non‑negative range `[0, n-1]`,
/// - removes factors of 2 from `a` while flipping the sign according to `n mod 8`,
/// - applies the quadratic reciprocity law,
/// - swaps and repeats until the remainder becomes zero.
///
/// The result is `-1`, `0`, or `1`.
///
/// - Precondition: `n != 0` (denominator must not be zero).
/// - Precondition: `!(a == .min && n == -1)` (division would overflow).
///
/// - Parameters:
///   - a: The numerator.
///   - n: The denominator (must be positive and odd for a meaningful Jacobi symbol).
/// - Returns: The Jacobi symbol value.
func jacobi(a: Int, n: Int) -> Int {
    // Mirror the assembly's preconditions.
    precondition(n != 0, "Denominator must not be zero")
    precondition(!(a == .min && n == -1), "Division would overflow")

    var a = a
    var n = n

    // Reduce a modulo n to the range [0, n-1].
    a %= n
    if a < 0 {
        a += n
    }

    // If the remainder is zero, the symbol is 0 unless n == 1.
    if a == 0 {
        return n == 1 ? 1 : 0
    }

    var sign = 1

    while true {
        // Remove all factors of 2 from a.
        // For every removed factor, flip the sign if n ≡ 3 or 5 (mod 8).
        while a & 1 == 0 {
            if n & 7 == 3 || n & 7 == 5 {
                sign = -sign
            }
            a >>= 1
        }

        // Now a is odd – apply the quadratic reciprocity step.
        // If both a and n are ≡ 3 (mod 4), flip the sign.
        if a & 3 == 3 && n & 3 == 3 {
            sign = -sign
        }

        // Swap a and n, then reduce the new a modulo the new n.
        let temp = a
        a = n % temp
        n = temp

        // If the new remainder is zero, the loop ends.
        if a == 0 {
            return n == 1 ? sign : 0
        }
    }
