/// Computes the Jaro–Winkler distance between two strings.
/// - Parameters:
///   - string: First string.
///   - string2: Second string.
/// - Returns: A value between 0.0 (identical) and 1.0 (completely different).
func jaroWinklerDistance(string: String, string2: String) -> Double {
    // Convert to character arrays for indexed access.
    let chars1 = Array(string)
    let chars2 = Array(string2)

    // Ensure the first array is the shorter one.
    if chars1.count > chars2.count {
        return jaroWinklerDistance(string: string2, string2: string)
    }

    let len1 = chars1.count
    let len2 = chars2.count

    // Handle empty strings.
    guard len1 > 0 else {
        return len2 == 0 ? 0.0 : 1.0
    }

    // Allowed distance for matching characters.
    let matchDistance = max(0, max(len1, len2) / 2 - 1)

    // Match flags for the shorter and longer strings.
    var shortMatch = [Bool](repeating: false, count: len1)
    var longMatch  = [Bool](repeating: false, count: len2)

    // Count of matching characters.
    var matches = 0

    // Find matches.
    for i in 0..<len1 {
        let start = max(0, i - matchDistance)
        let end   = min(len2 - 1, i + matchDistance)
        for j in start...end {
            if !longMatch[j] && chars1[i] == chars2[j] {
                shortMatch[i] = true
                longMatch[j]  = true
                matches += 1
                break
            }
        }
    }

    // No matches -> maximal distance.
    if matches == 0 {
        return 1.0
    }

    // Count transpositions.
    var k = 0
    var mismatches = 0
    for i in 0..<len1 where shortMatch[i] {
        while !longMatch[k] {
            k += 1
        }
        if chars1[i] != chars2[k] {
            mismatches += 1
        }
        k += 1
    }
    let transpositions = mismatches / 2

    // Jaro similarity.
    let mDouble = Double(matches)
    let similarity = (mDouble / Double(len1) +
                      mDouble / Double(len2) +
                      (mDouble - Double(transpositions)) / mDouble) / 3.0

    // Common prefix length (limited to 4).
    let maxPrefix = min(4, len1, len2)
    var prefix = 0
    while prefix < maxPrefix && chars1[prefix] == chars2[prefix] {
        prefix += 1
    }

    // Winkler adjustment.
    let winklerSimilarity = similarity + Double(prefix) * 0.1 * (1.0 - similarity)

    // Distance = 1 - similarity.
    return 1.0 - winklerSimilarity
}

