    let len1 = s1.count
    let len2 = s2.count

    // Handle empty strings
    if len1 == 0 && len2 == 0 {
        return 1.0
    }
    if len1 == 0 || len2 == 0 {
        return 0.0
    }

    // Compute the match distance (search window radius)
    let matchDistance: Int
    if len1 == 1 && len2 == 1 {
        // Special case for two single‑character strings (avoids negative distance)
        matchDistance = 1
    } else {
        let maxLen = max(len1, len2)
        matchDistance = maxLen / 2 - 1   // integer division, non‑negative because maxLen≥2 here
    }

    // Convert to character arrays for O(1) indexing
    let chars1 = Array(s1)
    let chars2 = Array(s2)

    // Flags for matched characters
