    if matches == 0 {
        return 0.0
    }

    // Second pass – count transpositions (mismatched pairs among the matches)
    var k = 0
    var mismatches = 0
    for i in 0..<len1 {
        if matched1[i] {
            while !matched2[k] {   // locate the next matched index in the second string
                k += 1
