/// A utility for working with Jordan–Pólya numbers.
///
/// A Jordan–Pólya number can be expressed as a product of factorials, i.e. ∏_{k} k!^{e_k}.
/// This class provides static methods to manipulate such representations.
class JordanPolyaNumbers {

    /// Converts a factorization dictionary into a human‑readable string.
    ///
    /// - Parameter factorization: A dictionary where each key is a factorial base `k`
    ///   and its value is the exponent `e_k` in the product ∏ k!^{e_k}.
    /// - Returns: A string representation like `"2!^3 * 3! * 5!^2"` (exponents of 1 are omitted).
    ///            For an empty dictionary or one that only contains `1!`, the result is `"1"`.
    static func toString(_ factorization: [Int: Int]) -> String {
        // Filter out the trivial factor 1! (1! = 1 does not affect the product).
        let components = factorization
            .filter { $0.key > 1 }
            .sorted(by: { $0.key < $1.key })
            .map { base, exp -> String in
                if exp == 1 {
                    return "\(base)!"
                } else {
                    return "\(base)!^\(exp)"
                }
            }

        guard !components.isEmpty else { return "1" }
        return components.joined(separator: " * ")
    }
}
