/// - Returns: A list of items that maximise total value while respecting the weight limit.
func knapsack(items: [KnapsackItem], limit: Int) -> [KnapsackItem] {
    let n = items.count
    guard n > 0, limit > 0 else { return [] }

    // dp[i][w] = best value using first i items with capacity w (1‑based indices)
    var dp = Array(repeating: Array(repeating: 0, count: limit + 1), count: n + 1)

