    /// - Returns: `true` if the square is available; otherwise `false`.
    func squareAvailable(_ point: CPoint) -> Bool {
        let x = point.x
        let y = point.y

        // Bounds check: the square must lie inside the board.
        guard x >= 0, x < size, y >= 0, y < size else {
            return false
        }

        // The square is available if it has not been visited yet.
        return board[x][y] == 0
    }
