class KnightsTour {
    // A point on the board
    struct Point {
        var x: Int
        var y: Int
    }

    private var board: [[Int]]      // 2‑D board, 0 = unvisited, step number otherwise
    let size: Int

    init(size: Int) {
        self.size = size
        board = Array(repeating: Array(repeating: 0, count: size), count: size)
    }

    // Knight move offsets (dx, dy)
    private static let knightMoves: [(dx: Int, dy: Int)] = [
        (2, 1), (1, 2), (-1, 2), (-2, 1),
        (-2, -1), (-1, -2), (1, -2), (2, -1)
    ]

    // Reset the board to all zeros
    private func reset() {
        for i in 0..<size {
            for j in 0..<size {
                board[i][j] = 0
            }
        }
    }

    // Check whether a point is inside the board and not yet visited
    private func isValid(_ point: Point) -> Bool {
        return point.x >= 0 && point.x < size &&
               point.y >= 0 && point.y < size &&
               board[point.x][point.y] == 0
    }

