```swift
/// Kosaraju's algorithm for strongly connected components.
///
/// Given a directed graph represented as an adjacency list (`graph`),
/// where vertices are numbered from `0` to `n-1`, returns an array `component`
/// such that `component[v]` is a representative vertex of the strongly 
/// connected component containing `v`.
///
/// - Parameter graph: adjacency list; `graph[i]` contains the indices of vertices
///                    reachable from vertex `i`.
/// - Returns: an array of length `graph.count` where each element is the root
///            (representative) of the SCC of that vertex.
func kosaraju(graph: [[Int]]) -> [Int] {
    let n = graph.count

    // ----------  Data structures  ----------
    // visited[v] == true if vertex v has been visited in the first DFS.
    var visited = [Bool](repeating: false, count: n)

    // Order in which vertices finish the first DFS.
    // Will be filled by appending vertices as they finish.
    var order = [Int]()

    // component[v] == -1 means vertex v not yet assigned to an SCC;
    // otherwise it holds the representative (root) of its SCC.
    var component = [Int](repeating: -1, count: n)

    // Reversed graph: for each vertex, list of incoming edges.
    var reversed = [[Int]](repeating: [], count: n)

    // ----------  Build reversed graph  ----------
    for (u, neighbors) in graph.enumerated() {
        for v in neighbors {
            reversed[v].append(u)
        }
    }

    // ----------  First DFS (original graph)  ----------
    func visit(_ u: Int) {
        visited[u] = true
        for v in graph[u] {
            if !visited[v] {
                visit(v)
            }
        }
        order.append(u)         // record finishing order
    }

    for v in 0..<n where !visited[v] {
        visit(v)
    }

    // ----------  Second DFS (reversed graph)  ----------
    func assign(_ u: Int, root: Int) {
        component[u] = root
        for v in reversed[u] {
            if component[v] == -1 {
                assign(v, root: root)
            }
        }
    }

    // Process vertices in reverse finishing order (i.e., from last finished to first).
    for v in order.reversed() where component[v] == -1 {
        assign(v, root: v)
    }

    return component
}
