/// Computes the Kronecker product of two matrices represented as 2D arrays of Int.
/// The result is a matrix where each element of `m1` is multiplied by the entire `m2` matrix.
///
/// - Parameters:
///   - m1: The first matrix (non‑empty, rectangular).
///   - m2: The second matrix (non‑empty, rectangular).
/// - Returns: The Kronecker product of `m1` and `m2`.
func kronecker(m1: [[Int]], m2: [[Int]]) -> [[Int]] {
    let rows1 = m1.count
    let cols1 = m1[0].count
    let rows2 = m2.count
    let cols2 = m2[0].count

    let totalRows = rows1 * rows2
    let totalCols = cols1 * cols2

    // Initialize result with zeros
    var result = Array(repeating: Array(repeating: 0, count: totalCols), count: totalRows)

    for i in 0..<rows1 {
        let rowBase = i * rows2
        for j in 0..<cols1 {
            let a = m1[i][j]
            let colBase = j * cols2
            for k in 0..<rows2 {
                let row = rowBase + k
                for l in 0..<cols2 {
                    let b = m2[k][l]
                    result[row][colBase + l] = a * b
                }
            }
        }
    }

    return result
}
