import Foundation

/// Returns the last Friday of each month in the specified year.
/// - Parameter year: The year for which to compute the dates.
/// - Returns: An array of `Date` values, one per month.
func lastFridays(of year: Int) -> [Date] {
    let calendar = Calendar.current
    return (1...12).compactMap { month in
        var components = DateComponents()
        components.year = year
        components.month = month
        // In the Gregorian calendar, Sunday = 1, Friday = 6.
        components.weekday = 6
        // A negative ordinal yields the last occurrence in the month.
        components.weekdayOrdinal = -1
        return calendar.date(from: components)
    }
}
