/// Computes the Levenshtein edit distance between two strings.
///
/// The edit distance is the minimum number of insertions, deletions,
/// or substitutions required to transform `string1` into `string2`.
///
/// - Parameters:
///   - string1: The first string.
///   - string2: The second string.
/// - Returns: The Levenshtein distance (non‑negative integer).
func levenshteinDistance(_ string1: String, _ string2: String) -> Int {
    let len1 = string1.count
    let len2 = string2.count

    // Base cases: if one string is empty, the distance is the length of the other.
    if len1 == 0 { return len2 }
    if len2 == 0 { return len1 }

    // `previousRow` stores distances for prefixes of string1 that have already been processed.
    // Initially it corresponds to the empty prefix of string1: 0, 1, 2, …, len2.
    var previousRow = Array(0...len2)

    // `currentRow` will be built for the next prefix of string1.
    var currentRow = [Int](repeating: 0, count: len2 + 1)

    // Outer loop: each character of string1 (with its index i).
    for (i, char1) in string1.enumerated() {
        // The first cell of the current row always equals i+1 (deleting all i+1 characters).
        currentRow[0] = i + 1

        // `diag` holds the value from previousRow[j] (the diagonal cell) before it is overwritten.
        // For j == 0 this is previousRow[0] which equals i.
        var diag = i

        // Inner loop: each character of string2 (with its index j).
        for (j, char2) in string2.enumerated() {
            let above = previousRow[j + 1] // distance after deleting char1
            let left  = currentRow[j]      // distance after inserting char2

            if char1 == char2 {
                // Characters match – no extra cost, take the diagonal value.
                currentRow[j + 1] = diag
            } else {
                // Characters differ – take the minimum of the three possible edits and add 1.
                currentRow[j + 1] = min(above, left, diag) + 1
            }

            // Prepare diag for the next iteration: the current `above` becomes the next diagonal.
            diag = above
        }

        // Swap the rows so that the current row becomes the previous row for the next character.
        swap(&previousRow, &currentRow)
    }

    // After processing all characters of string1, the answer lies in previousRow[len2].
    return previousRow[len2]
}

