/// A `Sequence` that generates prime numbers less than a given limit
/// using the Sieve of Eratosthenes.
struct Eratosthenes: IteratorProtocol, Sequence {
    /// Exclusive upper bound – primes returned are strictly less than this value.
    private let limit: Int
    /// Precomputed square root of `limit`, used to avoid unnecessary sieving.
    private let sqrtLimit: Int
    /// Current candidate number.
    private var current: Int
    /// `isPrime[i]` indicates whether `i` is (still) considered prime.
    /// The array has size `limit + 1` so that indices match the numbers themselves.
    private var isPrime: [Bool]

    /// Creates a sieve that will generate all primes less than `limit`.
    /// - Parameter limit: Exclusive upper bound; must be non‑negative.
    init(upTo limit: Int) {
        self.limit = limit
        self.sqrtLimit = Int(Double(limit).squareRoot())
        self.current = 2
        self.isPrime = [Bool](repeating: true, count: limit + 1)
        if limit >= 0 { isPrime[0] = false }
        if limit >= 1 { isPrime[1] = false }
    }

    /// Returns the next prime number, or `nil` if all primes have been returned.
    mutating func next() -> Int? {
        // Loop over candidates until the bound is reached.
        while current < limit {
            // Increment the candidate after the loop body, no matter how we exit it.
            defer { current += 1 }

            if isPrime[current] {
                let prime = current
                // Sieve only if the prime is not larger than the square root of the limit.
                if prime <= sqrtLimit {
                    // Mark multiples starting from prime² as composite.
                    for multiple in stride(from: prime * prime, through: limit, by: prime) {
                        isPrime[multiple] = false
                    }
                }
                return prime
            }
        }
        return nil
    }
}

