extension Array where Element: Comparable {
    /// Returns the longest non‑decreasing subsequence of the array.
    ///
    /// The algorithm runs in O(n log n) time using patience sorting with a
    /// binary search to locate the insertion point of each element.
    ///
    /// - Returns: An array containing the elements of the longest
    ///            non‑decreasing subsequence in increasing order.
    func longestIncreasingSubsequence() -> [Element] {
        let n = self.count
        guard n > 0 else { return [] }

        // predecessors[i] = index of the previous element in the LIS
        // that ends at self[i]
        var predecessors = [Int](repeating: 0, count: n)

        // tails[l] = index of the smallest possible tail element
        // for a non‑decreasing subsequence of length l (1‑based).
        // tails[0] is unused except as a dummy predecessor.
        var tails = [Int](repeating: 0, count: n + 1)

        var length = 0 // current length of the longest subsequence found

        for (i, value) in self.enumerated() {
            // Binary search for the first position where self[tails[pos]] > value
            var lo = 1
            var hi = length
            while lo <= hi {
                // mid = ceil((lo + hi) / 2)
                let mid = (lo + hi + 1) / 2
                if self[tails[mid]] <= value {
                    lo = mid + 1
                } else {
                    hi = mid - 1
                }
            }

            let pos = lo   // insertion position (1‑based)
            predecessors[i] = tails[pos - 1]
            tails[pos] = i

            if pos > length {
                length = pos
            }
        }

        // Reconstruct the LIS by walking the predecessor chain backwards
        var result = [Element]()
        var k = tails[length]
        for _ in 0..<length {
            result.append(self[k])
            k = predecessors[k]
        }
        return result.reversed()
    }
}
