/// Computes the next look‑and‑say sequence from a given sequence of digits.
///
/// For example, `[1,1]` becomes `[2,1]` (two ones), and `[2,1]` becomes `[1,2,1,1]`.
func lookAndSay(_ sequence: [Int]) -> [Int] {
    guard !sequence.isEmpty else { return [] }

    var result = [Int]()
    var currentDigit = sequence[0]
    var count = 1

    for digit in sequence.dropFirst() {
        if digit == currentDigit {
            count += 1
        } else {
            result.append(count)
            result.append(currentDigit)
            currentDigit = digit
            count = 1
        }
    }

    result.append(count)
    result.append(currentDigit)
    return result
}
