/// Validates a string using the Luhn algorithm.
/// - Parameter string: The input string (typically a numeric identifier, may contain non‑digit characters which are ignored).
/// - Returns: `true` if the checksum is valid (i.e., sum modulo 10 equals 0), otherwise `false`.
func luhn(_ string: String) -> Bool {
    let sum = string.reversed().enumerated().map { offset, character -> Int in
        // Convert character to its numeric value; ignore non‑digit characters.
        guard let digit = character.wholeNumberValue else { return 0 }

        // Double every second digit starting from the second from the right.
        if offset % 2 == 1 {
            let doubled = digit * 2
            // If doubling gives a two‑digit number, sum its digits (equivalent to subtracting 9).
            return doubled > 9 ? doubled - 9 : doubled
        } else {
            return digit
        }
    }.reduce(0, +)

    // The checksum is valid if the total is a multiple of 10.
    return sum % 10 == 0
}
