/// Computes the Möbius function μ(n).
///
/// Returns:
/// - 0 if n has a squared prime factor,
/// - 1 if n is a product of an even number of distinct primes,
/// - -1 if n is a product of an odd number of distinct primes.
/// For n == 1, the result is 1.
///
/// - Parameter number: A positive integer.
/// - Returns: The Möbius function value.
func mu(number n: Int) -> Int {
    var n = n

    // If 2² divides n, return 0 immediately.
    if n % 4 == 0 {
        return 0
    }

    var factorCount = 0

    // Extract the single factor 2 if present (n is even but not divisible by 4).
    if n & 1 == 0 {
        n /= 2
        factorCount += 1
        // n is now odd.
    }

    // n == 1 means only the factor 2 might have been taken.
    if n == 1 {
        return factorCount % 2 == 0 ? 1 : -1
    }

    // Small odd numbers (≤ 8) are known to be prime: 3, 5, 7.
    if n <= 8 {
        factorCount += 1
        return factorCount % 2 == 0 ? 1 : -1
    }

    // Trial division by odd numbers, up to √n.
    var divisor: Int = 3
    while divisor * divisor <= n {
        if n % divisor == 0 {
            let quotient = n / divisor
            // Check if divisor² divides the original n.
            if quotient % divisor == 0 {
                return 0
            }
            factorCount += 1
            n = quotient
            divisor += 2   // move to the next odd candidate
        } else {
            divisor += 2
        }
    }

    // Any remaining n > 1 is a prime factor.
    if n > 1 {
        factorCount += 1
    }

    return factorCount % 2 == 0 ? 1 : -1
}
