    let size: Int
    private var grid: [Point: Int] = [:]

    init(size: Int) {
        self.size = size
    }

    /// Creates an odd‑sized magic square using the Siamese method.
    /// - Returns: `self` after filling the square.
    /// - Throws: `MagicSquareError.invalidSize` if the size is not odd and positive.
    /// - Precondition: `size >= 3` (traps otherwise, as in the original assembly).
    func createOdd() throws -> MagicSquare {
        // ---- Size validation ----
        // The assembly throws an error only when size > 0 and even.
        // For size <= 0 or size odd the flow continues, but later a trap occurs
        // when size*size < 2 (i.e., size = 1). We mimic that with a precondition.
        guard size > 0 && size % 2 == 1 else {
            throw MagicSquareError.invalidSize
        }
        precondition(size >= 3, "Size must be at least 3")

        // ---- Place the first number (1) ----
        var row = 0
        var col = size / 2
        grid[Point(x: col, y: row)] = 1

        // ---- Place numbers 2 ... size*size ----
        for num in 2 ... size * size {
            // 1. Try moving up and right
            var nextRow = row - 1
            var nextCol = col + 1

            // 2. Wrap around the square
            if nextRow < 0 { nextRow = size - 1 }
            if nextCol >= size { nextCol = 0 }

            // 3. If the target cell is already occupied, move down instead
            if grid[Point(x: nextCol, y: nextRow)] != nil {
                nextRow = row + 1
                nextCol = col
                // Wrap if necessary (down)
                if nextRow >= size { nextRow = 0 }
            }

            // 4. Place the number
