/// Returns a Boolean value indicating whether the given integer is prime.
///
/// This implementation uses a classic optimised trial division algorithm:
/// - Exclude numbers less than 2.
/// - Check divisibility by 2 and 3 explicitly.
/// - Recognise that every prime greater than 3 is of the form 6k±1.
/// - For numbers less than 25 after these checks, the remaining candidates are prime.
/// - Otherwise test divisibility by numbers of the form 6k±1 up to the square root.
///
/// - Parameter n: The integer to test.
/// - Returns: `true` if `n` is prime, otherwise `false`.
func isPrime(_ n: Int) -> Bool {
    // Numbers less than 2 are not prime.
    if n < 2 { return false }

    // Even numbers: only 2 is prime.
    if n % 2 == 0 { return n == 2 }

    // Multiples of 3: only 3 is prime.
    if n % 3 == 0 { return n == 3 }

    // All remaining numbers below 25 are prime (5,7,11,13,17,19,23).
    if n < 25 { return true }

    // Trial division by numbers of the form 6k ± 1.
    var i = 5
    while i * i <= n {
        if n % i == 0 { return false }
        if n % (i + 2) == 0 { return false }
        i += 6
    }
    return true
}
