/// - Returns: `true` if `n` is magnanimous, `false` otherwise.
///
/// - Note: This function relies on `isPrime` (not shown) which tests primality of an `Int`.
///   Overflow in addition or multiplication will trap, as in the original assembly.
func isMagnanimous(_ n: Int) -> Bool {
    // Numbers with fewer than two digits are trivially magnanimous.
    if n < 10 {
        return true
    }

    var divisor = 10
    while divisor <= n {
        let quotient = n / divisor
        let remainder = n % divisor
        let sum = quotient + remainder

        if !isPrime(sum) {
            return false
        }

        // Continue with the next power of ten.
        divisor *= 10
    }

    return true
}

